From f06d99e5645eba5e184fcda003fbaf02e07fe787 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:01:13 +0100
Subject: [PATCH] applets/notes: open the context menu at the click position

On Wayland a window menu is placed against its parent item's whole
rectangle, so in a long, scrolled note it opened far below the click.
Open it from a 1x1 item that is moved to the click point instead.

BUG: 527703
---
 applets/notes/qml/main.qml | 11 ++++++++++-
 1 file changed, 10 insertions(+), 1 deletion(-)

diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..3d3bc1a2d 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -279,7 +279,9 @@ PlasmoidItem {
                     onPressed: event => {
                         if (event.button === Qt.RightButton) {
                             event.accepted = true;
-                            contextMenu.popup();
+                            contextMenuAnchor.x = event.x;
+                            contextMenuAnchor.y = event.y;
+                            contextMenu.popup(contextMenuAnchor, 0, 0);
                             forceActiveFocus();
                         }
                         if (event.button === Qt.LeftButton && contextMenu.visible === true) {
@@ -296,6 +298,13 @@ PlasmoidItem {
                         }
                     }

+                    // On Wayland a window menu opens below its whole parent item, so its parent is this point at the click
+                    Item {
+                        id: contextMenuAnchor
+                        width: 1
+                        height: 1
+                    }
+
                     QQC2.Menu {
                         id: contextMenu
                         popupType: QQC2.Menu.Window
-- 
